import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"32、【恒】 巽下震上","description":"横渠易说 - 32、【恒】 巽下震上","frontmatter":{"title":"32、【恒】 巽下震上","description":"横渠易说 - 32、【恒】 巽下震上"},"headers":[],"relativePath":"zh/classics/hengqu/034.md","filePath":"zh/classics/hengqu/034.md"}'),l={name:"zh/classics/hengqu/034.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_32、【恒】-巽下震上" tabindex="-1">32、【恒】 巽下震上 <a class="header-anchor" href="#_32、【恒】-巽下震上" aria-label="Permalink to “32、【恒】 巽下震上”">​</a></h1><h3 id="彖曰-恒-久也-刚上而柔下-雷风相与-巽而动-刚柔皆应-恒。-恒亨无咎利贞-久于其道也-天地之道恒久而不已也。-利有攸往-终则有始也。日月得天而能久照-四时变化而能久成-圣人久于其道而天下化成-观其所恒而天地万物之情可见矣。" tabindex="-1">彖曰：恒，久也，刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。“恒亨无咎利贞”，久于其道也，天地之道恒久而不已也。“利有攸往”，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成，观其所恒而天地万物之情可见矣。 <a class="header-anchor" href="#彖曰-恒-久也-刚上而柔下-雷风相与-巽而动-刚柔皆应-恒。-恒亨无咎利贞-久于其道也-天地之道恒久而不已也。-利有攸往-终则有始也。日月得天而能久照-四时变化而能久成-圣人久于其道而天下化成-观其所恒而天地万物之情可见矣。" aria-label="Permalink to “彖曰：恒，久也，刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。“恒亨无咎利贞”，久于其道也，天地之道恒久而不已也。“利有攸往”，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成，观其所恒而天地万物之情可见矣。”">​</a></h3><h3 id="象曰-雷风恒-君子以立不易方。" tabindex="-1">象曰：雷风恒，君子以立不易方。 <a class="header-anchor" href="#象曰-雷风恒-君子以立不易方。" aria-label="Permalink to “象曰：雷风恒，君子以立不易方。”">​</a></h3><p>观书当不以文害辞，如云义者出于思虑忖度，易言“天地之大义”，则天地固无思虑。“天地之情”“天地之心”皆放此。</p><h3 id="初六-浚恒-贞凶-无攸利。-象曰-浚恒之凶-始求深也。" tabindex="-1">初六，浚恒，贞凶，无攸利。 象曰：浚恒之凶，始求深也。 <a class="header-anchor" href="#初六-浚恒-贞凶-无攸利。-象曰-浚恒之凶-始求深也。" aria-label="Permalink to “初六，浚恒，贞凶，无攸利。 象曰：浚恒之凶，始求深也。”">​</a></h3><p>柔巽在下以应于上，持用为常，求之过深也。故人道之交贵乎中礼，且久渐而成也。持一作特。</p><h3 id="九二-悔亡。-象曰-九二悔亡-能久中也。" tabindex="-1">九二，悔亡。 象曰：“九二悔亡”，能久中也。 <a class="header-anchor" href="#九二-悔亡。-象曰-九二悔亡-能久中也。" aria-label="Permalink to “九二，悔亡。 象曰：“九二悔亡”，能久中也。”">​</a></h3><p>以阳系阴，用以为常，不能无悔，以其久中故免。</p><h3 id="九三-不恒其德-或承之羞-贞吝。-象曰-不恒其德-无所容也。" tabindex="-1">九三，不恒其德，或承之羞，贞吝。 象曰：“不恒其德”，无所容也。 <a class="header-anchor" href="#九三-不恒其德-或承之羞-贞吝。-象曰-不恒其德-无所容也。" aria-label="Permalink to “九三，不恒其德，或承之羞，贞吝。 象曰：“不恒其德”，无所容也。”">​</a></h3><p>进则犯上，退则乘刚，故动则招悔取辱，惟常守一德，庶几取容，故曰不恒其德则无所容也。一有“虽然贞吝，德则可常也”。</p><h3 id="九四-田无禽。-象曰-久非其位-安得禽也" tabindex="-1">九四，田无禽。 象曰：久非其位，安得禽也! <a class="header-anchor" href="#九四-田无禽。-象曰-久非其位-安得禽也" aria-label="Permalink to “九四，田无禽。 象曰：久非其位，安得禽也!”">​</a></h3><p>田以时至则禽或可得，处常非位则功无以致，故君子降志辱身，不可常也。</p><h3 id="六五-恒其德贞-妇人吉-夫子凶。-象曰-妇人贞吉-从一而终也-夫子制义-从妇凶也。" tabindex="-1">六五，恒其德贞，妇人吉，夫子凶。 象曰：妇人贞吉，从一而终也；夫子制义，从妇凶也。 <a class="header-anchor" href="#六五-恒其德贞-妇人吉-夫子凶。-象曰-妇人贞吉-从一而终也-夫子制义-从妇凶也。" aria-label="Permalink to “六五，恒其德贞，妇人吉，夫子凶。 象曰：妇人贞吉，从一而终也；夫子制义，从妇凶也。”">​</a></h3><h3 id="上六-振恒-凶。-象曰-振恒在上-大无功也。" tabindex="-1">上六，振恒，凶。 象曰：振恒在上，大无功也。 <a class="header-anchor" href="#上六-振恒-凶。-象曰-振恒在上-大无功也。" aria-label="Permalink to “上六，振恒，凶。 象曰：振恒在上，大无功也。”">​</a></h3><p>卦例于上爻多处之以贵而无位，高而无民，至恒又不可以此处，但见其不常在上，故大无功也。 易道灼然义理分明，自存乎卦，惟要人玩之乃得。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
